\begin{proposition}[Spectral theorem (cf. Theorem III.1.2 of \cite{Faraut1994})]
\label{prop:spectral}
Let $(\mathbb{E}, \circ)$ be a Euclidean Jordan algebra having rank $r$. 
For any $x \in \mathbb{E} $, there exist real numbers $\lambda_1 , \dots , \lambda_r$ and a Jordan frame $c_1 , \dots , c_r $ for which the following holds:
\begin{equation}
x = \sum_{i=1}^r \lambda_i c_i \notag.
\end{equation}
The numbers $\lambda_1 , \dots , \lambda_r$ are uniquely determined {\em eigenvalues} of $x$ (with their multiplicities).
Furthermore, ${\rm trace}(x) := \sum_{i=1}^r \lambda_i$, $\det(x) := \prod_{i=1}^r \lambda_i$.
\end{proposition}

A proper cone is symmetric if it is self-dual and homogeneous. 
It is known that the set of squares $\mathcal{K} = \{ x^2 : x \in \mathbb{E} \}$ is the symmetric cone of  $\mathbb{E}$  (cf. Theorems III.2.1 and III.3.1 of \cite{Faraut1994}).
The following properties can be derived from the results in \cite{Faraut1994}, as in  Corollary 2.3 of \cite{Yoshise2007}:
\begin{proposition}
\label{prop:lambda-Jordan}
Let $x \in \mathbb{E}$ and let $\sum_{j=1}^r \lambda_j c_j$ be a decomposition of $x$ given by Propositoin \ref{prop:spectral}. Then
\begin{description}
\item[(i)]
$x \in \mathcal{K}$ if and only if  $\lambda_j \geq 0 \ (j=1,2,\ldots,r)$, 
\item[(ii)]
$x \in {\rm int} \hspace{0.75mm} \mathcal{K}$ if and only if $\lambda_j > 0 \ (j=1,2,\ldots,r)$.
\end{description}
\end{proposition}

From Propositions \ref{prop:spectral} and \ref{prop:lambda-Jordan} for any $x \in \mathbb{E}$, its projection $P_\mathcal{K} (x)$ onto $\mathcal{K}$ can be written as an operation to round all negative eigenvalues of $x$ to $0$, i.e., 
$P_\mathcal{K} (x) = \sum_{i=1}^r [\lambda_i]^+ c_i$, where $[\cdot]^+$ denotes the projection onto the nonnegative orthant.

We focus on the feasibility of the following problem ${\rm P}_{S_{\infty}}(\mathcal{A})$, which is equivalent to  ${\rm P}(\mathcal{A})$: 
\begin{equation}
\begin{array}{lllllllll}
{\rm P}_{S_{\infty}}(\mathcal{A})&	&\mbox{find}   &x \in \mbox{int} \hspace{0.75mm} \mathcal{K}	&	&\mbox{s.t.}	&\mathcal{A} (x) = \bm{0},	&\|x\|_\infty \leq 1.
\end{array}
\notag
\end{equation}
The alternative problem ${\rm D}(\mathcal{A})$ of ${\rm P}(\mathcal{A})$ is 
\begin{equation}
\notag
\begin{array}{llllllllll}
{\rm D}(\mathcal{A})	&	&\mbox{find}   &y \in \mathcal{K}	&	&\mbox{s.t.}	&y \in \mbox{range} \hspace{0.3mm} \mathcal{A}^*,	&y \neq \bm{0},
\end{array}
\end{equation}
where  $\mbox{range} \hspace{0.3mm} \mathcal{A}^*$ is the orthogonal complement of $\mbox{ker} \hspace{0.3mm} \mathcal{A}$.
As we mentioned in section \ref{subsec:symmetric cone}, 
we assume that $\mathcal{K}$ is given by a Cartesian product of $p$ simple symmetric cones $\mathcal{K}_\ell (\ell=1, \ldots, p)$, i.e., $\mathcal{K} = \mathcal{K}_1 \times \dots \times \mathcal{K}_p $.

