\begin{proposition}
\label{prop:upper-bound-direct}
Suppose that, for any $v \in \mbox{\rm range} \hspace{0.3mm} \mathcal{A}^*$, the $\ell$-th block element $v_\ell$ of $v \in \mathbb{E}$ is decomposed into $v_\ell = \sum_{i=1}^{r_\ell} {\lambda(v_\ell)}_i {c(v_\ell)}_i$ as in Proposition \ref{prop:spectral}.
For each $\ell \in \{1,\ldots,p \}$ and $i \in \{1,\ldots,r_p\}$, define
\begin{equation}
\label{eq:q_ell,i(alpha)}
q_{\ell,i}(\alpha) := \left[ 1 - \alpha {\lambda(v_\ell)}_i \right]^+ + \sum_{k \neq i}^{r_\ell} \left[ -\alpha {\lambda(v_\ell)}_k \right]^+ + \sum_{j \neq \ell}^p \sum_{k=1}^{r_j} \left[  -\alpha {\lambda(v_j)}_k \right]^+ .
\end{equation}
Then, the following relations hold for any feasible solution $x$ of ${\rm P}_{S_{\infty}}(\mathcal{A})$, $\ell \in \{1,\ldots,p \}$ and $i \in \{1,\ldots,r_p\}$.
\begin{equation}
\label{eq:upper-bound-direct1}
\langle {c(v_\ell)}_i , x_\ell \rangle \leq  \min_{\alpha \in \mathbb{R} } q_{\ell,i}(\alpha) =
\begin{cases}
\min \left\{  1 ,  \left \langle  e , \mathcal{P}_{\mathcal{K}} \left( -  \frac{1}{{\lambda(v_\ell)}_i} v  \right) \right \rangle \right\} & \mbox{if ${\lambda(v_\ell)}_i \neq 0$}, \\
1 & \mbox{if ${\lambda(v_\ell)}_i = 0$} 
\end{cases}
.
\end{equation}
\end{proposition}

