\begin{lemma}
\label{lemma:0}
Let $(\mathbb{E}, \circ)$ be a Euclidean Jordan algebra with the \modifySecond{associated} symmetric cone $\mathcal{K}$.
For any $y \in \mathbb{E}$, the following equation holds:
\begin{equation}
\max_{\bm{0} \leq \lambda(x) \leq \bm{1}} \langle y ,x \rangle  =  \left \langle \mathcal{P}_\mathcal{K} \left( y \right)  ,e \right \rangle . \notag
\end{equation}
\end{lemma}

\begin{proof}
Using the decomposition $y = \sum_{i=1}^r \lambda_i c_i$ obtained by Proposition \ref{prop:spectral}, we see that 
\begin{equation}
\max_{\bm{0} \leq \lambda(x) \leq \bm{1}} \langle y ,x \rangle  = \max_{\bm{0} \leq \lambda(x) \leq \bm{1}} \left \langle \sum_{i=1}^r \lambda_i c_i , x \right \rangle = \max_{\bm{0} \leq \lambda(x) \leq \bm{1}}  \sum_{i=1}^r \lambda_i  \left \langle c_i , x \right \rangle . \label{lemma:0-eq1}
\end{equation}
Noting that $x \in \mathcal{K}, e-x \in \mathcal{K}$ from $\bm{0} \leq \lambda(x) \leq \bm{1}$, since $c_i \in \mathcal{K}$ is primitive idempotent, we find that 
$\langle c_i,x \rangle \geq 0$ and $\langle c_i, e-x \rangle \geq 0$, which implies that $0 \leq \langle c_i,x \rangle \leq 1$.
Thus, letting $I_1$ be the set of indices for which $\lambda_i \leq 0$ and $I_2$ be the set of indices for which $\lambda_i > 0$, if there exists an $x$ satisfying 
\begin{equation}
\langle c_i,x \rangle =
\begin{cases}
0 & i \in I_1 \\
1 & i \in I_2
\end{cases}, 
\label{lemma:0-eq2}
\end{equation}
then such an $x$ is an optimal solution of (\ref{lemma:0-eq1}). In fact, if we define $x^* = \sum_{i \in I_2} c_i$, then by the dedfinition of the Jordan frame, $x^*$ satisfies (\ref{lemma:0-eq2}) and $\bm{0} \leq \lambda(x) \leq \bm{1}$ and becomes an optimal solution of (\ref{lemma:0-eq1}). In this case, the optimal value of (\ref{lemma:0-eq1}) turns out to be
\begin{equation}
\max_{\bm{0} \leq \lambda(x) \leq \bm{1}}  \sum_{i=1}^r \lambda_i  \left \langle c_i , x \right \rangle = \sum_{i=1}^r \lambda_i  \left \langle c_i , x^* \right \rangle 
= \sum_{i \in I_2} \lambda_i 
= \sum_{i=1}^r [\lambda_i]^+
= \langle \mathcal{P}_\mathcal{K} (y) , e \rangle. 
\notag
\end{equation}
\end{proof}

\begin{proposition}
\label{prop:p-d-relation} 
Let $(\mathbb{E}, \circ)$ be a Euclidean Jordan Algebra with the corresponding symmetric cone  $\mathcal{K}$.
For a given $c \in \mathbb{E}$, consider the problem
\begin{equation}
\notag
\begin{array}{llllll}
\mbox{\rm max}	&\langle c , x \rangle 	&	&\mbox{\rm s.t}	&\mathcal{A}(x) = \bm{0},	&\bm{0} \leq \lambda (x) \leq \bm{1}  \notag.
\end{array}
\end{equation}
The dual problem of the above is 
\begin{equation}
\notag
\begin{array}{lllll}
\mbox{\rm min}	&\left \langle \mathcal{P}_\mathcal{K} \left( c - u  \right) , e \right \rangle	&	&\mbox{\rm s.t}	&u \in \mbox{\rm range} \hspace{0.3mm} \mathcal{A}^*. \notag
\end{array}
\end{equation}
\end{proposition}

\begin{proof}
Define the Lagrangian function $L(x,w)$ as $L(x,w) :=   \langle c , x \rangle -  w^\top \mathcal{A}(x)$ where $w \in \mathbb{R}^m$ is the Lagrange multiplier. 
\modifyThird{
Supoose that $x^*$ is an optimal sotution of the primal problem. 
Then, for any $w \in \mathbb{R}^m$,  we have $\langle c,x^* \rangle = L(w,x^*) \leq \max_{\bm{0} \leq \lambda(x) \leq \bm{1}} L(w,x)$, and hence,}
\begin{align*}
\modifyThird{\langle c, x^* \rangle} \leq \min_w \max_{\bm{0} \leq \lambda(x) \leq \bm{1}} L(x,w)
&=  \min_w \max_{\bm{0} \leq \lambda(x) \leq \bm{1}} \{  \langle c , x \rangle - \langle \mathcal{A}^*(w) ,x \rangle \}  \\
&=  \min_w \max_{\bm{0} \leq \lambda(x) \leq \bm{1}} \{  \langle c -  \mathcal{A}^*(w) ,x \rangle \}  \\
&=  \min_w   \left \langle \mathcal{P}_\mathcal{K} \left( c -  \mathcal{A}^*(w) \right)  ,e \right \rangle \ \ \ \mbox{(by  lemma \ref{lemma:0})}  \\
&= \min_{u \in \mbox{\footnotesize range} \mathcal{A}^*}  \langle \mathcal{P}_\mathcal{K} \left( c - u \right) , e \rangle.
\end{align*}
%and the dual problem is 
%\begin{equation}
%\notag
%\begin{array}{lllll}
%\mbox{\rm min}	&\left \langle \mathcal{P}_\mathcal{K} \left( c - u  \right) , e \right \rangle	&	&\mbox{\rm s.t}	&u \in \mbox{\rm range} \hspace{0.3mm} \mathcal{A}^*. \notag
%\end{array}
%\end{equation}
\end{proof}

\begin{proposition}
\label{prop:upper-bound}

Suppose that $v \in \mbox{\rm range} \hspace{0.3mm} \mathcal{A}^*$ is given by $v = \sum_{i=1}^r \lambda_i c_i$ as in Proposition \ref{prop:spectral}. 
For each $i \in \{ 1, \dots , r \}$ and $\alpha \in \mathbb{R}$, define $q_i(\alpha) := \left[    1-\alpha \lambda_i  \right]^+ + \sum_{j \neq i }^r \left[ -  \alpha \lambda_j  \right]^+$.
Then, the following relations hold for any $x \in F_{{\rm P}_{S_{\infty}}(\mathcal{A})}$ and $i \in \{ 1, \dots , r \}$\modifySecond{:}
\begin{equation}
\label{eq:bound_q}
\langle c_i , x \rangle \leq  
\min_{\alpha \in \mathbb{R}} q_i(\alpha) = 
\begin{cases}
\min \left\{  1 ,  \left \langle  e , \mathcal{P}_{\mathcal{K}} \left( -  \frac{1}{\lambda_i} v  \right) \right \rangle \right\} & \mbox{if $\lambda_i \neq 0$}, \\
1 & \mbox{if $\lambda_i = 0$}\modifySecond{.}
\end{cases}
\end{equation}
\end{proposition}

\begin{proof}

For each $i \in \{ 1, 2, \dots , r \}$, we have 
\begin{equation}
\mathcal{P}_\mathcal{K} \left( c_i -  \alpha v \right) = \mathcal{P}_\mathcal{K} \left( c_i - \alpha \sum_{j=1}^r \lambda_j c_j \right) = \mathcal{P}_\mathcal{K} \left( (1-\alpha \lambda_i ) c_i -   \sum_{j \neq i }^r \alpha \lambda_j c_j  \right), \notag
\end{equation}
and hence, 
\begin{equation}
\label{eq:q_i(alpha)}
\left \langle \mathcal{P}_\mathcal{K} \left( c_i -  \alpha v \right) , e \right \rangle
=
\left \langle \mathcal{P}_\mathcal{K} \left(    (1-\alpha \lambda_i ) c_i -   \sum_{j \neq i }^r \alpha \lambda_j c_j   \right) , \sum_{i=1}^r c_i \right \rangle 
= \left[    1-\alpha \lambda_i  \right]^+ + \sum_{j \neq i }^r \left[ -  \alpha \lambda_j  \right]^+  = q_i(\alpha) .
\end{equation}

Note that, since $q_i(\alpha)$ is a piece-wise linear convex function, if $\lambda_i = 0$, it attains the minimum at $\alpha = 0$ with $q_i(0) = 1$, and if $\lambda_i \neq 0$, it attains the minimum at $\alpha = 0$ with $q_i(0) = 1$ or at $\alpha =  \frac{1}{\lambda_i}$ with
\begin{equation}
\notag
q \left( \frac{1}{\lambda_i} \right) = \sum_{j \neq i}^r \left[ - \frac{\lambda_j}{\lambda_i}  \right]^+ 
= \sum_{j=1}^r \left[ - \frac{\lambda_j}{\lambda_i}  \right]^+ 
= \left \langle e , \mathcal{P}_{\mathcal{K}} \left( -  \frac{1}{\lambda_i} v  \right) \right \rangle.
\end{equation}
Thus, we obtain equivalence in (\ref{eq:bound_q}).
Since $\alpha v \in \mbox{range} \hspace{0.3mm} \mathcal{A}^*$ for all $\alpha \in \mathbb{R}$, 
for each $i \in \{ 1, \dots , r \}$, Proposition \ref{prop:p-d-relation} and  (\ref{eq:q_i(alpha)})  ensure that 
$\langle c_i , x \rangle \leq  \left \langle \mathcal{P}_\mathcal{K} \left( c_i -  \alpha v \right) , e \right \rangle = q_i(\alpha)$
for all $\alpha \in \mathbb{R}$, which implies the inequality in (\ref{eq:bound_q}).
\end{proof}

\begin{proof}
Let $c \in \mathbb {E}$ be an element whose $\ell$-th block element is $c_\ell = c (v_\ell)_i$ and other block elements take $0$.
For any real number $\alpha \in \mathbb{R}$, Proposition \ref {prop:p-d-relation} ensures that
\begin{align}
\label{eq:upper-bound-direct2}
\langle {c(v_\ell)}_i , x_\ell \rangle = \langle c,x \rangle &\leq \left \langle \mathcal{P}_\mathcal{K} \left( c -  \alpha v \right) , e \right \rangle \notag \\
&= \left \langle \mathcal{P}_{\mathcal{K}_\ell} \left( {c(v_\ell)}_i -  \alpha v_\ell \right) , e_\ell \right \rangle + \sum_{j \neq \ell}^p \left \langle \mathcal{P}_{\mathcal{K}_j} \left( -  \alpha v_j \right) , e_j \right \rangle \notag \\
&= \left[ 1 - \alpha {\lambda(v_\ell)}_i \right]^+ + \sum_{k \neq i}^{r_\ell} \left[ -\alpha {\lambda(v_\ell)}_k \right]^+ + \sum_{j \neq \ell}^p \sum_{k=1}^{r_j} \left[  -\alpha {\lambda(v_j)}_k \right]^+  = q_{\ell,i}(\alpha). 
\end{align}
We obtain (\ref{eq:upper-bound-direct1}) by following a similar argument to the one used in the proof of Proposition \ref{prop:upper-bound}.
\end{proof}

