\max_{\bm{0} \leq \lambda(x) \leq \bm{1}} \langle y ,x \rangle  =  \left \langle \mathcal{P}_\mathcal{K} \left( y \right)  ,e \right \rangle . \notag
\end{equation}
\end{lemma}

\begin{proof}
Using the decomposition $y = \sum_{i=1}^r \lambda_i c_i$ obtained by Proposition \ref{prop:spectral}, we see that 
\begin{equation}
\max_{\bm{0} \leq \lambda(x) \leq \bm{1}} \langle y ,x \rangle  = \max_{\bm{0} \leq \lambda(x) \leq \bm{1}} \left \langle \sum_{i=1}^r \lambda_i c_i , x \right \rangle = \max_{\bm{0} \leq \lambda(x) \leq \bm{1}}  \sum_{i=1}^r \lambda_i  \left \langle c_i , x \right \rangle . \label{lemma:0-eq1}
\end{equation}
Noting that $x \in \mathcal{K}, e-x \in \mathcal{K}$ from $\bm{0} \leq \lambda(x) \leq \bm{1}$, since $c_i \in \mathcal{K}$ is primitive idempotent, we find that 
$\langle c_i,x \rangle \geq 0$ and $\langle c_i, e-x \rangle \geq 0$, which implies that $0 \leq \langle c_i,x \rangle \leq 1$.
