\begin{equation}
\langle c_i,x \rangle =
\begin{cases}
0 & i \in I_1 \\
1 & i \in I_2
\end{cases}, 
\label{lemma:0-eq2}
\end{equation}
then such an $x$ is an optimal solution of (\ref{lemma:0-eq1}). In fact, if we define $x^* = \sum_{i \in I_2} c_i$, then by the dedfinition of the Jordan frame, $x^*$ satisfies (\ref{lemma:0-eq2}) and $\bm{0} \leq \lambda(x) \leq \bm{1}$ and becomes an optimal solution of (\ref{lemma:0-eq1}). In this case, the optimal value of (\ref{lemma:0-eq1}) turns out to be
\begin{equation}
\max_{\bm{0} \leq \lambda(x) \leq \bm{1}}  \sum_{i=1}^r \lambda_i  \left \langle c_i , x \right \rangle = \sum_{i=1}^r \lambda_i  \left \langle c_i , x^* \right \rangle 
= \sum_{i \in I_2} \lambda_i 
= \sum_{i=1}^r [\lambda_i]^+
= \langle \mathcal{P}_\mathcal{K} (y) , e \rangle. 
\notag
\end{equation}
