\begin{proposition}
\label{prop:upper-bound}

Suppose that $v \in \mbox{\rm range} \hspace{0.3mm} \mathcal{A}^*$ is given by $v = \sum_{i=1}^r \lambda_i c_i$ as in Proposition \ref{prop:spectral}. 
For each $i \in \{ 1, \dots , r \}$ and $\alpha \in \mathbb{R}$, define $q_i(\alpha) := \left[    1-\alpha \lambda_i  \right]^+ + \sum_{j \neq i }^r \left[ -  \alpha \lambda_j  \right]^+$.
Then, the following relations hold for any $x \in F_{{\rm P}_{S_{\infty}}(\mathcal{A})}$ and $i \in \{ 1, \dots , r \}$\modifySecond{:}
\begin{equation}
\label{eq:bound_q}
\langle c_i , x \rangle \leq  
\min_{\alpha \in \mathbb{R}} q_i(\alpha) = 
\begin{cases}
\min \left\{  1 ,  \left \langle  e , \mathcal{P}_{\mathcal{K}} \left( -  \frac{1}{\lambda_i} v  \right) \right \rangle \right\} & \mbox{if $\lambda_i \neq 0$}, \\
1 & \mbox{if $\lambda_i = 0$}\modifySecond{.}
\end{cases}
\end{equation}
\end{proposition}

\begin{proof}

For each $i \in \{ 1, 2, \dots , r \}$, we have 
\begin{equation}
\mathcal{P}_\mathcal{K} \left( c_i -  \alpha v \right) = \mathcal{P}_\mathcal{K} \left( c_i - \alpha \sum_{j=1}^r \lambda_j c_j \right) = \mathcal{P}_\mathcal{K} \left( (1-\alpha \lambda_i ) c_i -   \sum_{j \neq i }^r \alpha \lambda_j c_j  \right), \notag
\end{equation}
and hence, 
\begin{equation}
\label{eq:q_i(alpha)}
\left \langle \mathcal{P}_\mathcal{K} \left( c_i -  \alpha v \right) , e \right \rangle
=
\left \langle \mathcal{P}_\mathcal{K} \left(    (1-\alpha \lambda_i ) c_i -   \sum_{j \neq i }^r \alpha \lambda_j c_j   \right) , \sum_{i=1}^r c_i \right \rangle 
= \left[    1-\alpha \lambda_i  \right]^+ + \sum_{j \neq i }^r \left[ -  \alpha \lambda_j  \right]^+  = q_i(\alpha) .
\end{equation}

Note that, since $q_i(\alpha)$ is a piece-wise linear convex function, if $\lambda_i = 0$, it attains the minimum at $\alpha = 0$ with $q_i(0) = 1$, and if $\lambda_i \neq 0$, it attains the minimum at $\alpha = 0$ with $q_i(0) = 1$ or at $\alpha =  \frac{1}{\lambda_i}$ with
\begin{equation}
\notag
q \left( \frac{1}{\lambda_i} \right) = \sum_{j \neq i}^r \left[ - \frac{\lambda_j}{\lambda_i}  \right]^+ 
= \sum_{j=1}^r \left[ - \frac{\lambda_j}{\lambda_i}  \right]^+ 
= \left \langle e , \mathcal{P}_{\mathcal{K}} \left( -  \frac{1}{\lambda_i} v  \right) \right \rangle.
\end{equation}
Thus, we obtain equivalence in (\ref{eq:bound_q}).
Since $\alpha v \in \mbox{range} \hspace{0.3mm} \mathcal{A}^*$ for all $\alpha \in \mathbb{R}$, 
for each $i \in \{ 1, \dots , r \}$, Proposition \ref{prop:p-d-relation} and  (\ref{eq:q_i(alpha)})  ensure that 
$\langle c_i , x \rangle \leq  \left \langle \mathcal{P}_\mathcal{K} \left( c_i -  \alpha v \right) , e \right \rangle = q_i(\alpha)$
for all $\alpha \in \mathbb{R}$, which implies the inequality in (\ref{eq:bound_q}).
\end{proof}

