\label{eq:q_ell,i(alpha)}
q_{\ell,i}(\alpha) := \left[ 1 - \alpha {\lambda(v_\ell)}_i \right]^+ + \sum_{k \neq i}^{r_\ell} \left[ -\alpha {\lambda(v_\ell)}_k \right]^+ + \sum_{j \neq \ell}^p \sum_{k=1}^{r_j} \left[  -\alpha {\lambda(v_j)}_k \right]^+ .
\end{equation}
Then, the following relations hold for any feasible solution $x$ of ${\rm P}_{S_{\infty}}(\mathcal{A})$, $\ell \in \{1,\ldots,p \}$ and $i \in \{1,\ldots,r_p\}$.
